Executed independent consumer probe on Rust 1.100.0/macOS arm64 against path runlimit-core at 7cc8c82e. Both characterization tests passed, proving the unwanted panic escapes. No repository source changed. Reproducer (dependency: runlimit-core path):

#[cfg(test)]
mod tests {
    use runlimit_core::{Observer, Observation, CleanupObservation, CleanupOutcome, observe_safely};
    use runlimit_core::attempts::{AttemptObserver, AttemptObservation, observe_attempt_safely};
    struct Payload;
    impl Drop for Payload { fn drop(&mut self) { panic!("payload destructor escaped"); } }
    struct Callback;
    impl Observer for Callback { fn observe(&self, _: &Observation<'_>) { std::panic::panic_any(Payload); } }
    impl AttemptObserver for Callback { fn observe(&self, _: AttemptObservation) { std::panic::panic_any(Payload); } }
    #[test]
    fn quota_observer_payload_destruction_escapes_isolation() {
        let result = std::panic::catch_unwind(|| observe_safely(&Callback, &Observation::Cleanup(CleanupObservation::new(1, CleanupOutcome::NoEffect, std::time::Duration::ZERO))));
        assert!(result.is_err(), "characterization: callback payload destruction escapes");
    }
    #[test]
    fn attempt_observer_payload_destruction_escapes_isolation() {
        let result = std::panic::catch_unwind(|| observe_attempt_safely(&Callback, AttemptObservation::Admitted));
        assert!(result.is_err(), "characterization: callback payload destruction escapes");
    }
}
